import fs from 'node:fs';
import cp from 'node:child_process';
import crypto from 'node:crypto';
const [output, before, after, ...workloads] = process.argv.slice(2);
const shell = (cmd, args = []) => cp.execFileSync(cmd, args, {encoding: 'utf8'}).trim();
const sha = p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
if (shell('git', ['status', '--porcelain', '--untracked-files=no'])) throw Error('Dirty tracked inputs');
const result = {
  date: new Date().toISOString(), kind: 'Debug process diagnostic, not production throughput',
  candidate: shell('git', ['rev-parse', 'HEAD']),
  zig: shell('/Users/glennmichaeltorregosa/zig-aarch64-macos-0.17.0-dev.1770+5d7cf3f34/zig', ['version']),
  regex: shell('git', ['-C', '../zig-regex', 'rev-parse', 'HEAD']),
  gc: shell('git', ['-C', '/private/tmp/zig-js-json-gc.qLuelH', 'rev-parse', 'HEAD']),
  corpus: shell('git', ['-C', 'test262', 'rev-parse', 'HEAD']),
  host: shell('/usr/sbin/sysctl', ['-n', 'machdep.cpu.brand_string']),
  memory: shell('/usr/sbin/sysctl', ['-n', 'hw.memsize']),
  os: shell('/usr/bin/sw_vers'), power: shell('/usr/bin/pmset', ['-g', 'batt']),
  binaries: {before: {path: before, sha256: sha(before)}, after: {path: after, sha256: sha(after)}},
  controller: fs.readFileSync(new URL(import.meta.url), 'utf8'),
  inputs: workloads.map(path => ({path, sha256: sha(path), source: fs.readFileSync(path, 'utf8')})),
  samples: []
};
for (let pair = 1; pair <= 7; pair++) {
  for (const [index, path] of workloads.entries()) {
    const order = (pair + index) % 2 ? ['before', 'after'] : ['after', 'before'];
    for (const variant of order) {
      const cmd = [result.binaries[variant].path, '--eval', path, 'tree'];
      const proc = cp.spawnSync('/usr/bin/time', ['-l', ...cmd], {encoding: 'utf8', timeout: 90000});
      const combined = proc.stdout + proc.stderr;
      if (proc.status !== 0 || !/^OK [0-9]+$/m.test(combined)) throw Error(combined);
      const timing = combined.match(/([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys/);
      const counter = name => Number(combined.match(new RegExp('(\\d+)\\s+' + name))[1]);
      result.samples.push({pair, workload: path, variant, command: ['/usr/bin/time', '-l', ...cmd],
        checksum: combined.match(/^OK (\d+)$/m)[1], wall: +timing[1], user: +timing[2], sys: +timing[3],
        instructions: counter('instructions retired'), cycles: counter('cycles elapsed'),
        peakFootprint: counter('peak memory footprint'), maxRSS: counter('maximum resident set size'),
        stdout: proc.stdout, stderr: proc.stderr});
    }
  }
}
for (const {path} of result.inputs) {
  const rows = result.samples.filter(s => s.workload === path);
  if (new Set(rows.map(s => s.checksum)).size !== 1) throw Error('Checksum divergence');
  const median = (v, key) => rows.filter(s => s.variant === v).map(s => s[key]).sort((a,b) => a-b)[3];
  console.log(path, JSON.stringify(Object.fromEntries(['wall','user','instructions','peakFootprint'].map(k => [k, [median('before',k),median('after',k)]]))));
}
if (shell('git', ['status', '--porcelain', '--untracked-files=no'])) throw Error('Inputs changed during collection');
fs.writeFileSync(output, JSON.stringify(result, null, 2) + '\n');

