  var parsed = JSON.parse(text);
  if (parsed.length !== 4096 || parsed[0] !== 123456789.5 || parsed[4095] !== 123460884.5) throw new Error("bad result");
  sum += parsed.length + parsed[0] + parsed[4095];
}
sum;

